    "node": ">=20"
  },
  "description": "A small TypeScript/JavaScript Lambda module that configures Powertools Logger, binds the AWS request ID, and logs a safe request event without copying the full event.",
  "license": "Apache-2.0",
  "dependencies": {
    "@aws-lambda-powertools/logger": "2.36.0"
  }
